import{_ as i,r as t,o as c,c as r,e as o,a as n,s as e,d as s}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Components - October CMS - 3.x","titleTemplate":false,"description":"Configurable controllers that can be attached to any page, partial or layout.","frontmatter":{"subtitle":"Configurable controllers that can be attached to any page, partial or layout."},"headers":[{"level":2,"title":"Introduction","slug":"introduction","link":"#introduction","children":[]},{"level":2,"title":"Components Aliases","slug":"components-aliases","link":"#components-aliases","children":[]},{"level":2,"title":"Using External Property Values","slug":"using-external-property-values","link":"#using-external-property-values","children":[]},{"level":2,"title":"Passing Variables to Components","slug":"passing-variables-to-components","link":"#passing-variables-to-components","children":[]},{"level":2,"title":"Customizing Default Markup","slug":"customizing-default-markup","link":"#customizing-default-markup","children":[{"level":3,"title":"Moving Default Markup to a Partial","slug":"moving-default-markup-to-a-partial","link":"#moving-default-markup-to-a-partial","children":[]},{"level":3,"title":"Overriding Component Partials","slug":"overriding-component-partials","link":"#overriding-component-partials","children":[]}]},{"level":2,"title":"The \\"View Bag\\" Component","slug":"the-view-bag-component","link":"#the-view-bag-component","children":[{"level":3,"title":"AJAX Handlers and Partials","slug":"ajax-handlers-and-partials","link":"#ajax-handlers-and-partials","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"3.x/cms/themes/components.md","filePath":"3.x/cms/themes/components.md"}'),u={name:"3.x/cms/themes/components.md"};function d(m,a,g,k,h,v){const p=t("pre-heading"),l=t("post-heading");return c(),r("div",null,[o(p),a[0]||(a[0]=n("h1",null,"Components",-1)),o(l),a[1]||(a[1]=e(`<p>Components are a key feature of building scalable and modern solutions with October CMS. Each component implements some functionality that extends your website. Components can output HTML markup on a page, but it is not necessary - other important features of components are <a href="./../ajax/introduction.html">handling AJAX requests</a>, handling form postbacks and handling the page execution cycle, that allows to inject variables to pages or implement the website security.</p><p>This article describes the components basics and doesn&#39;t explain how to use <a href="./../ajax/handlers.html">components with AJAX</a>, <a href="./../../extend/cms-components.html">developing components</a> as part of plugins, or the <a href="./../components/section.html">components included</a> with October CMS.</p><h2 id="introduction"><a href="#introduction" class="header-anchor">#</a> Introduction</h2><p>Components can be found in the Editor in the admin panel. You can add components to your pages, partials and layouts by clicking the Components toolbar button on any open document. If you use a text editor you can attach a component to a page or layout by adding its name to the configuration section of the template file. The next example demonstrates how to add a demo To-Do component to a page.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Components demonstration</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/components</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- HTML Content Here --&gt;</span>
</code></pre></div></div><p>This initializes the component with the properties that are defined in the component section. Many components have properties, but it is not a requirement. Some properties are required, and some properties have default values. If you are not sure what properties are supported by a component, refer to the documentation provided by the developer, or use the Inspector in the Editor admin panel. The Inspector opens when you click a component in the page or layout component panel.</p><div class="custom-block aside"><p>If two components with the same name are assigned to a page and layout together, the page component will take priority.</p></div><p>When you refer a component, it automatically creates a page variable that matches the component name (<code>demoTodo</code> in the previous example). Components that provide HTML markup can be rendered on a page with the <code>{% component %}</code> tag, like the following.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block warning"><p>Using components inside partials has limited functionality, this is described in more detail in the <a href="./partials.html">Dynamic Partials section</a> of the documentation.</p></div><h2 id="components-aliases"><a href="#components-aliases" class="header-anchor">#</a> Components Aliases</h2><p>If there are two plugins that register components with the same name, you can attach a component by using its fully qualified class name and assigning it an <em>alias</em>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">October\\Demo\\Components\\Todo demoTodoAlias</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><p>The first parameter in the section is the class name, the second is the component alias name that will be used when attached to the page. If you specified a component alias you should use it everywhere in the page code when you refer to the component. Note that the next example refers to the component alias:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The aliases also allow you to define multiple components of the same class on a same page by using the short name first and an alias second. This lets you to use multiple instances of a same component on a page.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoA</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">10</span>
<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoB</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><h2 id="using-external-property-values"><a href="#using-external-property-values" class="header-anchor">#</a> Using External Property Values</h2><p>By default property values are initialized in the Configuration section where the component is defined, and the property values are static, like this:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,20)),a[2]||(a[2]=n("div",null,[n("p",null,[s("However there is a way to initialize properties with values loaded from external parameters - URL parameters or "),n("a",{href:"./partials.html"},"partial"),s(" parameters (for components defined in partials). Use the "),n("code",{"v-pre":""},"{{ paramName }}"),s(" syntax for values that should be loaded from partial variables:")])],-1)),a[3]||(a[3]=e(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>Assuming that in the example above the component <strong>demoTodo</strong> is defined in a partial, it will be initialized with a value loaded from the <strong>maxItems</strong> partial variable:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>my-todo-partial<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>10<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You may use dot notation to retrieve a deeply nested value from an external parameter:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ data.maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,5)),a[4]||(a[4]=n("div",null,[n("p",null,[s("To load a property value from the URL parameter, use the "),n("code",{"v-pre":""},"{{ :paramName }}"),s(" syntax, where the name starts with a colon ("),n("code",{"v-pre":""},":"),s("), for example.")])],-1)),a[5]||(a[5]=e(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ :maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>The page that the component belongs to should have a corresponding <a href="./pages.html">URL parameter</a> defined.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/todo/:maxItems</span>&quot;</span>
</code></pre></div><p>In the October back-end you can use the Inspector tool for assigning external values to component properties. In the Inspector you don&#39;t need to use the curly brackets to enter the parameter name. Each field in the Inspector has an icon on the right side, which opens the external parameter name editor. Enter the parameter name as <code>paramName</code> for partial variables or <code>:paramName</code> for URL parameters.</p><h2 id="passing-variables-to-components"><a href="#passing-variables-to-components" class="header-anchor">#</a> Passing Variables to Components</h2><p>Components can be designed to use variables at the time they are rendered, similar to <a href="./partials.html">Partial variables</a>, they can be specified after the component name in the <code>{% component %}</code> tag. The specified variables will explicitly override the value of the <a href="./../../extend/cms-components.html">component properties</a>, including external property values.</p><p>In this example, the <strong>maxItems</strong> property of the component will be set to <em>7</em> at the time the component is rendered:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>7<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="customizing-default-markup"><a href="#customizing-default-markup" class="header-anchor">#</a> Customizing Default Markup</h2><div class="custom-block aside"><p>The default markup in a component is boilerplate code, with the aim to provide a simple example of how it can be used.</p></div><p>There are two ways to customize the default markup of a component:</p><ul><li>copy the default markup in to your theme</li><li>override a component partial one at a time</li></ul><p>Overriding a component partial has a very limited subset of uses. In most cases, converting a component&#39;s partial to a CMS partial is much easier, and there is little difference in doing it this way.</p><p>As an example, take a look at a blog component rendered like this.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blog</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>blog<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>The code above is effectively the same as doing this.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blog</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog::default<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>If you copy the <strong>default.htm</strong> partial from the component to your theme as a <strong>blog-default.htm</strong> partial, you can render it the same way.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blog</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog-default<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Here we can see it simple to use CMS partials to customize the content, and it demonstrates the true power of components. There are only rare cases where the theme should override components partials and this is covered in more detail below.</p><h3 id="moving-default-markup-to-a-partial"><a href="#moving-default-markup-to-a-partial" class="header-anchor">#</a> Moving Default Markup to a Partial</h3><p>Each component will have an entry point partial called <strong>default.htm</strong> that is rendered when the <code>{% component %}</code> tag is called, in the following example we will assume the component is called <strong>blogPost</strong>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blog/post</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>blogPost<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>The output will be rendered from the plugin directory <strong>components/blogpost/default.htm</strong>. You can copy all the markup from this file and paste it directly in the page or to a new partial, called <strong>blog-post.htm</strong> for example.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Inside the markup you may notice references to a variable called <code>__SELF__</code>, this refers to the component object and should be replaced with the component alias used on the page, in this example it is <code>blogPost</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>This is the only change needed to allow the default component markup to work anywhere inside the theme. Now the component markup can be customized and rendered using the theme partial.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog-post<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>This process can be repeated for all other partials found in the component partial directory.</p><h3 id="overriding-component-partials"><a href="#overriding-component-partials" class="header-anchor">#</a> Overriding Component Partials</h3><p>All component partials can be overridden using the theme partials. This is useful when a component has a strict implementation and introduces as an option to configure specific areas of its markup.</p><p>As an example, if a component called <strong>channel</strong> uses the <strong>title.htm</strong> partial.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">mypage</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">channel</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>channel<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>We can override the partial by creating a file in our theme called <strong>partials/channel/title.htm</strong>.</p><p>The file path segments are broken down like this:</p><div class="table"><table tabindex="0"><thead><tr><th>Segment</th><th>Description</th></tr></thead><tbody><tr><td><strong>partials</strong></td><td>the theme partials directory</td></tr><tr><td><strong>channel</strong></td><td>the component alias (a partial subdirectory)</td></tr><tr><td><strong>title.htm</strong></td><td>the component partial to override</td></tr></tbody></table></div><p>The partial subdirectory name can be customized to anything by simply assigning the component an alias of the same name. For example, by assigning the <strong>channel</strong> component with a different alias <strong>foobar</strong> the override directory is also changed.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">channel foobar</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>foobar<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Now we can override the <strong>title.htm</strong> partial by creating a file in our theme called <strong>partials/foobar/title.htm</strong> instead.</p><h2 id="the-view-bag-component"><a href="#the-view-bag-component" class="header-anchor">#</a> The &quot;View Bag&quot; Component</h2><div class="custom-block aside"><p>The viewBag component is hidden in the backend panel and is only available for file-based editing. It can also be used by other plugins to store data.</p></div><p>There is a special component included in October CMS called <code>viewBag</code> that can be used on any page or layout. It allows ad hoc properties to be defined and accessed inside the markup area easily as variables. A good usage example is defining an active menu item inside a page.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">About</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/about.html</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">viewBag</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">activeMenu</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">about</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Page content...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Any property defined for the component is then made available inside the page, layout, or partial markup using the <code>viewBag</code> variable. For example, in this layout the <strong>active</strong> class is added to the list item if the <code>viewBag.activeMenu</code> value is set to <strong>about</strong>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Default layout</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>...

<span class="token comment">&lt;!-- Main navigation --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> viewBag<span class="token punctuation">.</span>activeMenu <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>about<span class="token punctuation">&#39;</span></span> <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>active<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>About<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h3 id="ajax-handlers-and-partials"><a href="#ajax-handlers-and-partials" class="header-anchor">#</a> AJAX Handlers and Partials</h3><p>Components may introduce <a href="./../ajax/introduction.html">AJAX handlers</a> and <a href="./partials.html">partials</a> to the a theme&#39;s life cycle, using a prefix of the component name and two <code>::</code> symbols. For example, all the AJAX handlers defined by components are available globally.</p><div class="language-html extra-class"><pre class="language-html"><code>data-request=&quot;onMyComponentHandler&quot;
</code></pre></div><p>However, if there is a conflict in naming, the fully qualified name can be used.</p><div class="language-html extra-class"><pre class="language-html"><code>data-request=&quot;componentName::onMyComponentHandler&quot;
</code></pre></div><p>Partials rendered from outside the component must use their fully qualified name.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>componentName::component-partial<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Read more on <a href="./../../extend/cms-components.html">component development</a> to learn about component partials.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../extend/cms-components.html">CMS Component Development</a></li></ul></div>`,56))])}const y=i(u,[["render",d]]);export{w as __pageData,y as default};
